package com.studywithlove.app;
import android.app.*;import android.content.*;import android.os.*;import java.util.*;
public class WeeklyReportReceiver extends BroadcastReceiver{
 public static void schedule(Context c){AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);Intent i=new Intent(c,WeeklyReportReceiver.class);PendingIntent pi=PendingIntent.getBroadcast(c,940,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Calendar x=Calendar.getInstance(TimeZone.getTimeZone("Asia/Baku"));x.set(Calendar.DAY_OF_WEEK,Calendar.SUNDAY);x.set(Calendar.HOUR_OF_DAY,19);x.set(Calendar.MINUTE,0);x.set(Calendar.SECOND,0);if(x.getTimeInMillis()<=System.currentTimeMillis())x.add(Calendar.WEEK_OF_YEAR,1);if(Build.VERSION.SDK_INT>=23){if(Build.VERSION.SDK_INT<31||am.canScheduleExactAlarms())am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,x.getTimeInMillis(),pi);else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,x.getTimeInMillis(),pi);}else am.setExact(AlarmManager.RTC_WAKEUP,x.getTimeInMillis(),pi);}
 @Override public void onReceive(Context c,Intent i){android.content.SharedPreferences p=c.getSharedPreferences("study_progress",0);int minutes=0,topics=0;Calendar cal=Calendar.getInstance(TimeZone.getTimeZone("Asia/Baku"));java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US);for(int d=0;d<7;d++){Calendar q=(Calendar)cal.clone();q.add(Calendar.DAY_OF_YEAR,-d);minutes+=p.getInt("focus_minutes_"+f.format(q.getTime()),0);}Set<String> days=p.getStringSet("study_days",new TreeSet<String>());topics=p.getInt("weekly_completed_topics",0);NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel("weekly_report","Недельный отчёт",NotificationManager.IMPORTANCE_DEFAULT));Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,"weekly_report"):new Notification.Builder(c);Intent open=new Intent(c,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(c,941,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);b.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Твоя неделя в Study with Love 🌸").setContentText("Фокус: "+minutes+" мин · "+days.size()+" учебных дней · "+topics+" новых тем").setStyle(new Notification.BigTextStyle().bigText("За неделю: "+minutes+" минут по таймеру, "+days.size()+" учебных дней и "+topics+" завершённых тем. Ты молодец — каждый шаг важен!")).setContentIntent(pi).setAutoCancel(true);nm.notify(942,b.build());schedule(c);}
}
